<template>
  <div
    class="po-replay-launcher"
    :class="{ 'po-replay-launcher--toolbar': toolbar }"
  >
    <FellowButton
      v-if="toolbar"
      icon="history"
      :aria-label="$t('po_replay_title')"
      data-test="po-replay-open"
      :blocked="
        !accessGranted || !available || (!allowDocumentInput && !validId(docId))
      "
      @click="openReplay"
    >
      <q-tooltip>
        {{
          accessGranted
            ? $t('po_replay_title')
            : $t('po_replay_access_required')
        }}
      </q-tooltip>
    </FellowButton>
    <button
      v-else
      type="button"
      class="po-replay-launcher__button"
      data-test="po-replay-open"
      :disabled="
        !accessGranted || !available || (!allowDocumentInput && !validId(docId))
      "
      :title="
        accessGranted
          ? $t('po_replay_readonly')
          : $t('po_replay_access_required')
      "
      @click="openReplay"
    >
      {{ $t('po_replay_title') }}
    </button>
    <q-dialog v-model="open" maximized data-test="po-replay-dialog">
      <q-card class="po-replay-launcher__dialog">
        <header>
          <h2>{{ $t('po_replay_title') }}</h2>
          <button type="button" @click="close">
            {{ $t('po_replay_close') }}
          </button>
        </header>
        <div class="po-replay-launcher__body" v-if="open && accessGranted">
          <p>{{ $t('po_replay_readonly') }}</p>
          <form v-if="allowDocumentInput" @submit.prevent="load">
            <label
              >{{ $t('po_replay_document_id') }}
              <input
                v-model="draftId"
                maxlength="200"
                autocomplete="off"
                spellcheck="false"
                @input="invalidate"
              />
            </label>
            <button type="submit" :disabled="loading || !validId(draftId)">
              {{ $t('po_replay_load') }}
            </button>
          </form>
          <div v-else class="po-replay-launcher__document">
            <span>{{ $t('po_replay_document_id') }}: {{ docId }}</span>
            <button type="button" :disabled="loading" @click="load">
              {{ $t('po_replay_reload') }}
            </button>
          </div>
          <p v-if="loading" role="status">{{ $t('po_replay_loading') }}</p>
          <p v-else-if="error" role="alert" data-test="po-replay-error">
            {{ $t(error) }}
          </p>
          <PoMatchReplayPlayer
            v-else-if="loadedId"
            :response="response"
            :doc-id="loadedId"
            :document-changed="documentChanged"
          />
        </div>
      </q-card>
    </q-dialog>
  </div>
</template>

<script setup lang="ts">
import {
  defineAsyncComponent,
  onBeforeUnmount,
  onMounted,
  ref,
  shallowRef,
  watch,
} from 'vue';
import FellowButton from 'src/single-component/FellowButton.vue';
import { useTouchlessAccess } from 'src/composables/useTouchlessAccess';
import {
  useActiveOrgId,
  useUserIdentityVersion,
} from 'src/utils/user-identity';
import { validReplayDocumentId } from 'src/utils/po-match-replay';

const PoMatchReplayPlayer = defineAsyncComponent(
  () => import('./PoMatchReplayPlayer.vue'),
);
const props = withDefaults(
  defineProps<{
    toolbar?: boolean;
    docId?: string;
    allowDocumentInput?: boolean;
    available?: boolean;
    documentChanged?: boolean;
    revision?: unknown;
  }>(),
  { docId: '', available: true },
);
const { accessGranted, checkAccess, ensureSettingsLoaded } =
  useTouchlessAccess();
const activeOrg = useActiveOrgId();
const identityVersion = useUserIdentityVersion();
const validId = validReplayDocumentId;
const open = ref(false);
const draftId = ref('');
const loadedId = ref('');
const response = shallowRef<unknown>(null);
const loading = ref(false);
const error = ref('');
let generation = 0;

function invalidate() {
  generation += 1;
  response.value = null;
  loadedId.value = '';
  error.value = '';
  loading.value = false;
}
function close() {
  open.value = false;
  invalidate();
}
function openReplay() {
  if (!props.available || !checkAccess()) return;
  open.value = true;
  if (!props.allowDocumentInput) void load();
}
async function load() {
  invalidate();
  const docId = (props.allowDocumentInput ? draftId.value : props.docId).trim();
  if (!open.value || !props.available || !checkAccess() || !validId(docId))
    return;
  const ownGeneration = generation;
  const org = activeOrg.value;
  const identity = identityVersion.value;
  const current = () =>
    open.value &&
    ownGeneration === generation &&
    props.available &&
    org === activeOrg.value &&
    identity === identityVersion.value &&
    checkAccess();
  loading.value = true;
  try {
    const { default: PoMatchExplanationService } =
      await import('src/services/analytics/PoMatchExplanationService');
    if (!current()) return;
    const service = new PoMatchExplanationService();
    const result = await service.getDocument(docId);
    if (!current()) return;
    loadedId.value = docId;
    response.value = result;
  } catch (failure: unknown) {
    if (!current()) return;
    const status =
      (failure as { response?: { status?: number }; status?: number })?.response
        ?.status ?? (failure as { status?: number })?.status;
    error.value = [401, 403, 404].includes(status ?? 0)
      ? 'po_replay_not_accessible'
      : 'po_replay_load_failed';
  } finally {
    if (current()) loading.value = false;
  }
}
watch(
  open,
  (value) => {
    if (!value) invalidate();
  },
  { flush: 'sync' },
);
watch(
  accessGranted,
  (value) => {
    if (!value) close();
  },
  { flush: 'sync' },
);
watch(
  [
    () => props.docId,
    () => props.available,
    () => props.revision,
    activeOrg,
    identityVersion,
  ],
  close,
  { flush: 'sync' },
);
onMounted(() => {
  void ensureSettingsLoaded();
});
onBeforeUnmount(close);
</script>

